import { z } from 'zod';
export const StockLogReasonSchema = z.enum([
    'sale',
    'purchase',
    'return',
    'damage',
    'expired',
    'sample',
    'correction',
    'initial',
    'manual_add',
    'audit_correction',
    'festival_kit_assembly',
    'pos_void',
]);
export const CreateItemSchema = z.object({
    name: z.string().min(1, 'Item name is required'),
    regionalName: z.string().optional(),
    category: z.string().min(1, 'Category is required'),
    sku: z.string().optional(),
    barcode: z.string().optional(),
    unit: z.string().default('pc'),
    subUnit: z.string().default('none'),
    subUnitsPerUnit: z.number().positive().default(1),
    subUnitName: z.string().optional(),
    costPrice: z.number().nonnegative().default(0),
    sellingPrice: z.number().nonnegative().default(0),
    mrp: z.number().nonnegative().optional(),
    stock: z.number().default(0),
    reorderLevel: z.number().int().nonnegative().default(5),
    hsn: z.string().optional(),
    gstPercent: z.number().nonnegative().default(0),
    batchNumber: z.string().optional(),
    expiryDate: z.string().optional(),
    shelfLocation: z.string().optional(),
    isLooseItem: z.boolean().default(false),
    isActive: z.boolean().default(true),
});
export const UpdateItemSchema = CreateItemSchema.partial();
export const AdjustStockSchema = z.object({
    change: z.number(),
    reason: StockLogReasonSchema,
    note: z.string().optional(),
});
export const ItemTableDefinition = {
    tableName: 'items',
    columns: [
        'id',
        'tenant_id',
        'name',
        'regional_name',
        'category',
        'sku',
        'barcode',
        'unit',
        'sub_unit',
        'sub_units_per_unit',
        'sub_unit_name',
        'cost_price',
        'selling_price',
        'mrp',
        'stock',
        'reorder_level',
        'hsn',
        'gst_percent',
        'batch_number',
        'expiry_date',
        'shelf_location',
        'is_loose_item',
        'is_active',
        'created_at',
        'updated_at',
    ],
    primaryKey: 'id',
    foreignKeys: [{ column: 'tenant_id', references: 'client_tenants(id)' }],
};
export const StockLogTableDefinition = {
    tableName: 'stock_logs',
    columns: ['id', 'tenant_id', 'date', 'item_id', 'item_name', 'qty_change', 'unit', 'reason', 'note'],
    primaryKey: 'id',
    foreignKeys: [
        { column: 'tenant_id', references: 'client_tenants(id)' },
        { column: 'item_id', references: 'items(id)' },
    ],
};
